import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
cut='2026-07-29'; D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).query('date<=@cut').sort_values('date').set_index('date') for s in U}
def run(h):
 rec=[]
 for s,x in D.items():
  r=x.close.pct_change(); eff=(x.close/x.close.shift(20)-1)/(r.abs().rolling(20).sum()+1e-12)
  y=x.close.shift(-h)/x.close-1
  rec.append(pd.DataFrame({'date':x.index,'f':eff,'y':y,'s':s}))
 a=pd.concat(rec).dropna(); vals=[]
 for dt,g in a.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: vals.append((dt,spearmanr(g.f,g.y).statistic,len(g)))
 z=pd.DataFrame(vals,columns=['date','ic','n']).set_index('date'); return z
z=run(1); print('20d trend efficiency; cutoff',cut,'dates',len(z),'avg_n',z.n.mean(),'coverage',len(pd.concat([pd.DataFrame({'f':(x.close/x.close.shift(20)-1)/(x.close.pct_change().abs().rolling(20).sum()+1e-12)}) for x in D.values()]).dropna())/sum(len(x) for x in D.values()),'IC',z.ic.mean(),'ICIR',z.ic.mean()/z.ic.std(ddof=1),'hit',(z.ic>0).mean())
for lo,hi in [('2020','2022-12-31'),('2023','2024-12-31'),('2025','2026-07-29')]:
 q=z.loc[lo:hi].ic; print('regime',lo,hi,len(q),q.mean(),q.mean()/q.std(ddof=1))
for h in [5,10,20]:
 q=run(h); print('decay',h,len(q),q.ic.mean(),q.ic.mean()/q.ic.std(ddof=1))
# rank turnover
frames=[]
for s,x in D.items():
 r=x.close.pct_change(); f=(x.close/x.close.shift(20)-1)/(r.abs().rolling(20).sum()+1e-12); frames.append(f.rename(s))
r=pd.concat(frames,axis=1).rank(axis=1,pct=True); print('turnover',r.diff().abs().mean(axis=1).mean(),'symbols',len(D))
# pooled correlations to common simple references
all=[]
for s,x in D.items():
 rng=(x.high-x.low).replace(0,np.nan); f=(x.close/x.close.shift(20)-1)/(x.close.pct_change().abs().rolling(20).sum()+1e-12)
 all.append(pd.DataFrame({'f':f,'clv':2*(x.close-x.low)/rng-1,'rev5':-(x.close/x.close.shift(5)-1),'mom20':x.close/x.close.shift(20)-1}))
print('corr',pd.concat(all).dropna().corr().f.round(4).to_dict())

import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; cut='2026-07-29'
D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).query('date<=@cut').sort_values('date').set_index('date') for s in U}
def factor(x): return (x.close/x.close.shift(20)-1)/(x.close.pct_change().abs().rolling(20).sum()+1e-12)
def run(h):
 rec=[]
 for s,x in D.items(): rec.append(pd.DataFrame({'date':x.index,'f':factor(x).values,'y':(x.close.shift(-h)/x.close-1).values,'s':s}))
 a=pd.concat(rec,ignore_index=True).dropna(); vals=[]
 for dt,g in a.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: vals.append((dt,spearmanr(g.f,g.y).statistic,len(g)))
 return pd.DataFrame(vals,columns=['date','ic','n']).set_index('date')
