import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; CUT='2026-07-15'
def load(p): return pd.read_csv(p,parse_dates=['date']).set_index('date').sort_index().query('date<=@CUT')
D={s:load('../persistent/stock_data/'+s+'.csv') for s in U}
# Cross-asset relative trend: 10d return minus contemporaneous equal-weight universe return,
# divided by 20d idiosyncratic volatility. Positive signal means persistent relative strength.
C=pd.concat([x.close.pct_change().rename(s) for s,x in D.items()],axis=1)
bench=C.mean(axis=1)
def factor(x,s):
 r=x.close.pct_change(); rel=(r-bench.reindex(x.index)).rolling(10,min_periods=8).sum()
 resid=(r-bench.reindex(x.index))
 vol=resid.rolling(20,min_periods=15).std()*np.sqrt(10)
 return (rel/vol).rename(s)
rows=[]
for s,x in D.items():
 f=factor(x,s); y=x.close.shift(-1)/x.close-1
 rows.append(pd.DataFrame({'date':x.index,'f':f,'y':y,'s':s}))
a=pd.concat(rows).dropna(); out=[]
for dt,g in a.groupby('date'):
 if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: out.append((dt,spearmanr(g.f,g.y).statistic,len(g)))
z=pd.DataFrame(out,columns=['date','ic','n']).set_index('date')
alln=sum(len(x) for x in D.values()); valid=sum(factor(x,s).notna().sum() for s,x in D.items())
ranks=pd.concat([factor(x,s) for s,x in D.items()],axis=1).rank(axis=1,pct=True)
