 m20=x.close.pct_change(20); m5=x.close.pct_change(5); m60=x.close.pct_change(60)
 agree=((np.sign(m5)==np.sign(m20)).astype(float)+ (np.sign(m60)==np.sign(m20)).astype(float))/2
 return (m20/vol)*agree
