import numpy as np,pandas as pd
from scipy.stats import spearmanr
from alphacrafter.sim.utils import get_stock_daily_data,get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
rows=[]
for s in U:
 d=get_stock_daily_data(s,3200)
 if d is None or len(d)<200: d=get_index_daily_data(s,3200)
 if d is not None and len(d):
  x=d[['date','close']].drop_duplicates('date'); x['symbol']=s; rows.append(x)
cl=pd.concat(rows).pivot(index='date',columns='symbol',values='close').sort_index().ffill(); r=cl.pct_change()
ret3=cl.pct_change(3)
disp=r.T.rolling(5).std().T
med=disp.rolling(60,min_periods=30).median()
state=(disp/med).clip(0.5,2.0)
f=(-ret3.mul(state,axis=0)).shift(1)
res={h:[] for h in [1,3,5,10]}
for dt in cl.index:
