 q=pd.DataFrame(q,columns=['date','n','ic']).set_index('date')
 print('H',h,'obs',len(q),'avgN %.2f'%q.n.mean(),'IC %.6f rawICIR %.6f annICIR %.4f hit %.4f'%(q.ic.mean(),q.ic.mean()/(q.ic.std(ddof=1)+1e-12),q.ic.mean()/(q.ic.std(ddof=1)+1e-12)*np.sqrt(252),(q.ic>0).mean()))
 for a,b in [('2020','2022'),('2023','2025'),('2026','2027'),('2028','2030')]:
  y=q.loc[a:b].ic
  if len(y): print(' ',a+'-'+b,len(y),'IC %.6f ICIR %.6f'%(y.mean(),y.mean()/(y.std(ddof=1)+1e-12)))
print('dates',len(px),'instruments',len(D),'coverage %.4f'%f.notna().mean().mean())
f.stack().rename('signal').reset_index().rename(columns={'level_0':'date','level_1':'symbol'}).to_csv('scripts/miner_2_20300627_downside_momentum_signal.csv',index=False)

