  for dt,r in z.iterrows(): rows.append((dt,s,h,r.sig,r.f))
x=pd.DataFrame(rows,columns=['date','symbol','h','sig','f'])
for h in [1,3,5]:
 y=x[x.h==h]; vals=[]
 for dt,g in y.groupby('date'):
