 if d is not None: D[s]=d.set_index('date')['close'].astype(float)
p=pd.DataFrame(D).sort_index().ffill(); r=np.log(p).diff()
# Conditional trend persistence: medium trend, risk-scaled, active only when cross-sectional breadth is not extreme.
# This tests whether moderate broad participation favors continuation versus the already heavily used reversal signals.
mom=r.rolling(40).sum(); vol=r.rolling(20).std()*np.sqrt(20)
breadth=(r.rolling(5).sum()>0).mean(axis=1)
active=((breadth>=.35)&(breadth<=.65)).astype(float)
f=(mom/vol).mul(active,axis=0).replace([np.inf,-np.inf],np.nan)
rows=[]
for t in f.index:
 j=r.index.searchsorted(t,side='right')
 for h in [1,3,5,10]:
  k=j+h-1
  if j>=len(r) or k>=len(r): continue
  z=pd.concat([f.loc[t],r.iloc[j:k+1].sum()],axis=1).dropna()
  if len(z)>=8: rows.append((t,h,z.iloc[:,0].corr(z.iloc[:,1]),len(z)))
x=pd.DataFrame(rows,columns=['date','h','ic','n'])
print('date_minmax',p.index.min(),p.index.max(),'dates',x.date.nunique(),'instruments',len(U),'coverage',round(f.notna().stack().mean(),5),'turnover',round(f.rank(axis=1,pct=True).diff().abs().mean().mean(),5))
for h in [1,3,5,10]:
