from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P={}
for s in U:
 d=get_index_daily_data(s,5000)
 if d is None or len(d)<300: d=get_stock_daily_data(s,5000)
 if d is not None and len(d): P[s]=d.set_index('date').close.astype(float)
pd_=pd.concat(P,axis=1).sort_index().ffill(); r=pd_.pct_change()
# equal-weight market proxy, correlation estimated only from trailing history ending t-1
m=r.mean(axis=1); corr=pd.DataFrame(index=r.index,columns=r.columns,dtype=float)
for s in r.columns: corr[s]=r[s].rolling(60,min_periods=40).corr(m)
f=(-corr).shift(1) # lower market correlation expected to diversify and lead
# forward 10d return, cross-sectional IC by date
fr=pd_/pd_.shift(10)-1
rows=[]
for dt in f.index:
