q=a.ic; print('dates',len(a),'avgN',a.n.mean(),'coverage',f.notna().sum().sum()/(f.shape[0]*len(U)))
print('IC %.8f ICIR %.8f hit %.4f turnover %.6f'%(q.mean(),q.mean()/q.std(ddof=1),(q>0).mean(),f.diff().abs().mean().mean()))
