import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 x=get_stock_daily_data(s,days=4000)
 if x is not None and len(x): D[s]=x.assign(date=pd.to_datetime(x.date)).set_index('date').close.astype(float)
p=pd.DataFrame(D).sort_index(); lr=np.log(p/p.shift(1)); r5=lr.rolling(5).sum(); v20=lr.rolling(20).std()
# high-dispersion short-term reversal: normalize reversal by own risk and activate above median cross-sectional dispersion
base=-(r5/v20); disp=lr.rolling(20).std().median(axis=1)
f=base.where(disp>disp.rolling(120).median(),0.0).rank(axis=1,pct=True); f=f.sub(f.mean(axis=1),axis=0)
ics=[]; ns=[]; prev=None; tos=[]
for dt in f.index:
 a=pd.concat([f.loc[dt],(p.shift(-10)/p-1).loc[dt]],axis=1).dropna()
 if len(a)>=8:
  ics.append(a.iloc[:,0].corr(a.iloc[:,1],method='spearman'));ns.append(len(a)); sig=f.loc[dt].rank(pct=True)
  if prev is not None:tos.append(np.nanmean(abs(sig-prev)))
  prev=sig
z=pd.Series(ics).dropna()
def st(x):return len(x),x.mean(),x.mean()/x.std(ddof=1),(x>0).mean()
print('dates',len(z),'avg_n',np.mean(ns),'coverage',np.mean(ns)/15,'IC/ICIR/hit',st(z),'turnover',np.nanmean(tos))
for k in [120,252,504]:print('recent',k,st(z.tail(k)))
print('last',p.index[-1])

import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def L(s):
 d=get_stock_daily_data(s,4200); return pd.Series(d.close.values,index=pd.to_datetime(d.date))
P=pd.DataFrame({s:L(s) for s in A}); R=np.log(P).diff();
# trend quality: 60d return divided by realized vol, with path efficiency confirmation
m=R.rolling(60).sum(); v=R.rolling(60).std()*np.sqrt(60); eff=m.abs()/(R.abs().rolling(60).sum()+1e-12)
f=m/(v+1e-12)*eff
F=f; ic=[]; ns=[]
for t in F.index:
 y=np.log(P.shift(-10)/P).loc[t]; x=F.loc[t]; ok=x.notna()&y.notna()
 if ok.sum()>=8: ic.append(x[ok].corr(y[ok])); ns.append(ok.sum())
ic=pd.Series(ic).dropna(); print('dates',len(ic),'avg_n',np.mean(ns),'coverage',F.notna().mean().mean(),'IC',ic.mean(),'ICIR',ic.mean()/ic.std(),'hit',(ic>0).mean(),'turnover',F.rank(pct=True).diff().abs().mean(axis=1).mean())
for w in [120,252,504]:
 q=ic.tail(w);print('recent',w,q.mean(),q.mean()/q.std())
for h in [1,5,10,20]:
 y=np.log(P.shift(-h)/P); z=[]
 for t in F.index:
  ok=F.loc[t].notna()&y.loc[t].notna()
  if ok.sum()>=8:z.append(F.loc[t,ok].corr(y.loc[t,ok]))
 q=pd.Series(z).dropna();print('decay',h,q.mean(),q.mean()/q.std())
print('period',ic.index.min(),ic.index.max())

import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 try: d=get_index_daily_data(s,3000)
 except: d=get_stock_daily_data(s,3000)
 if d is not None and len(d)>300: D[s]=d.set_index('date')['close'].astype(float)
p=pd.DataFrame(D).sort_index().ffill(); r=np.log(p).diff(); m=r.mean(axis=1)
rows=[]
for i in range(80,len(p)-10):
 f=pd.Series(index=p.columns,dtype=float); rr=r.iloc[max(0,i-40):i]
 for s in p.columns:
  b=rr[s].cov(m.iloc[max(0,i-40):i])/m.iloc[max(0,i-40):i].var()
  res=rr[s].iloc[-3:].sum()-b*m.iloc[max(0,i-3):i].sum(); vol=rr[s].std()
  f[s]=-res/(vol*np.sqrt(3)) if vol>1e-8 else np.nan
 fr=p.iloc[i+10]/p.iloc[i]-1; z=pd.concat([f.rename('f'),fr.rename('y')],axis=1).dropna()
 if len(z)>=8: rows.append((p.index[i],z.f.corr(z.y),len(z)))
ics=pd.Series([x[1] for x in rows],index=[x[0] for x in rows]); ns=pd.Series([x[2] for x in rows],index=ics.index)
print('dates',len(ics),'avgN',ns.mean(),'coverage',ns.mean()/15)
print('IC',ics.mean(),'ICIR',ics.mean()/ics.std(ddof=1),'hit',(ics>0).mean())
for n in [120,252,504]:
 q=ics.tail(n); print('recent',n,q.mean(),q.mean()/q.std(ddof=1),len(q))
for s in ['2020','2022','2024','2026','2028','2030','2032','2034']:
 q=ics[ics.index.astype(str).str.startswith(s)]
 if len(q): print(s,len(q),q.mean(),q.mean()/q.std(ddof=1))
ics.to_csv('scripts/miner_2_20341110_residual_reversal3_ic.csv')

import pandas as pd,numpy as np,os
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 f='../persistent/stock_data/'+s+'.csv'
 if os.path.exists(f):
  d=pd.read_csv(f); d.date=pd.to_datetime(d.date); D[s]=d.set_index('date').close
P=pd.DataFrame(D).sort_index(); r=P.pct_change(); vol=r.rolling(30).std()
# Intermediate-horizon trend acceleration: recent 20d return relative to prior 40d return, risk normalized.
F=((P.pct_change(20)-P.pct_change(60)/3).div(vol*np.sqrt(20))).shift(1)
F.to_csv('scripts/miner_2_20341124_acceleration_signal.csv',index_label='date')
print('assets',len(P.columns),'dates',len(P),'coverage',F.notna().mean().mean())
for h in [1,3,5,10,20]:
 a=[]; ns=[]
 for i in range(len(P)-h):
  z=pd.concat([F.iloc[i],P.iloc[i+h]/P.iloc[i]-1],axis=1).dropna()
  if len(z)>=8:
   a.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic); ns.append(len(z))
 a=np.asarray(a); ir=a.mean()/a.std(ddof=1)*np.sqrt(len(a))
 print('horizon',h,'dates',len(a),'avgN',np.mean(ns),'IC',a.mean(),'ICIR',ir,'hit',np.mean(a>0))
 if h==10:
  for n in [120,252,504,756,1260]:
   q=a[-n:];print('recent',n,'IC',q.mean(),'ICIR',q.mean()/q.std(ddof=1)*np.sqrt(len(q)))
# mean cross-sectional rank turnover
R=F.rank(axis=1,pct=True); print('turnover',np.nanmean(np.abs(R-R.shift(1)).mean(axis=1)))

